import re
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))

def f(A):
    H=len(A);W=len(A[0])
    from collections import Counter
    cnt=Counter(v for r in A for v in r)
    bg=cnt.most_common(1)[0][0]
    rb=[i for i in range(H) if len(set(A[i]))==1]
    cb=[j for j in range(W) if len({A[i][j] for i in range(H)})==1]
    def region(a,b):
        r0=(rb[a-1]+1 if a>0 else 0); r1=(rb[a]-1 if a<len(rb) else H-1)
        c0=(cb[b-1]+1 if b>0 else 0); c1=(cb[b]-1 if b<len(cb) else W-1)
        return (r0,r1,c0,c1)
    scores=[]
    for a in range(len(rb)+1):
        for b in range(len(cb)+1):
            r0,r1,c0,c1=region(a,b)
            n=sum(1 for i in range(r0,r1+1) for j in range(c0,c1+1) if A[i][j]!=bg)
            scores.append((n,a,b))
    _,sa,sb=max(scores)
    r0,r1,c0,c1=region(sa,sb)
    pat=[[A[i][j] for j in range(c0,c1+1)] for i in range(r0,r1+1)]
    out=[r[:] for r in A]
    for a in range(len(rb)+1):
        for b in range(len(cb)+1):
            if (a,b)==(sa,sb): continue
            r0i,r1i,c0i,c1i=region(a,b)
            for pi in range(len(pat)):
                for pj in range(len(pat[0])):
                    if r0i+pi<H and c0i+pj<W:
                        out[r0i+pi][c0i+pj]=pat[pi][pj]
    return out
